package paper.jane.offline;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 Board board; TextView status; Button tools; int ink=Color.BLACK; boolean eraser=false; Bitmap pendingExport; final java.util.concurrent.ExecutorService disk=java.util.concurrent.Executors.newSingleThreadExecutor(); final Handler main=new Handler(Looper.getMainLooper()); boolean loading=false,readFailed=false; int revision=0;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(244,240,231));getWindow().setNavigationBarColor(Color.rgb(40,42,44));
 FrameLayout root=new FrameLayout(this); board=new Board();root.addView(board,new FrameLayout.LayoutParams(-1,-1));
 status=new TextView(this);status.setTextSize(14);status.setTextColor(Color.DKGRAY);status.setPadding(dp(12),dp(6),dp(12),dp(6));status.setBackgroundColor(0xeef4f0e7);status.setText("Jane Paper · Offline prototype");FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.LEFT);root.addView(status,sp);
 tools=new Button(this);tools.setText("Tools · Pen");tools.setTextSize(18);tools.setContentDescription("Drawing tools");FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(dp(160),dp(60),Gravity.BOTTOM|Gravity.RIGHT);tp.setMargins(dp(12),dp(12),dp(12),dp(12));root.addView(tools,tp);tools.setOnClickListener(v->menu());setContentView(root);load();}
 void note(String s){status.setText(s);}
 void menu(){final String[] items={"Pen","Eraser","Black","Blue","Red","Green","Undo","Save locally","Reopen saved drawing","Export PNG","Clear canvas"};
 new AlertDialog.Builder(this).setTitle("Drawing tools").setItems(items,(d,n)->{switch(n){case 0:eraser=false;break;case 1:eraser=true;break;case 2:ink=Color.BLACK;eraser=false;break;case 3:ink=0xff205ac7;eraser=false;break;case 4:ink=0xffce3434;eraser=false;break;case 5:ink=0xff19844c;eraser=false;break;
 case 6:if(!board.lines.isEmpty()){board.lines.remove(board.lines.size()-1);board.dirty=true;board.invalidate();save();}break;
 case 7:save();break;case 8:save();loading=true;disk.execute(()->main.post(()->{loading=false;load();}));break;case 9:export();break;case 10:new AlertDialog.Builder(this).setTitle("Clear this drawing?").setMessage("This clears the canvas and its local saved copy. Export a PNG first if you want to keep it.").setNegativeButton("Cancel",null).setPositiveButton("Clear",(a,b)->{board.lines.clear();board.dirty=true;board.invalidate();save();}).show();break;}
 tools.setText(eraser?"Tools · Eraser":"Tools · Pen");}).show();}
 static class Stroke{int color;float width;ArrayList<float[]> points=new ArrayList<>();Stroke(int c,float w){color=c;width=w;}}
 class Board extends View{
 ArrayList<Stroke> lines=new ArrayList<>();Stroke current;int pointer=-1;Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);Bitmap cache;Canvas cached;boolean dirty=true;Path live=new Path();boolean moved;
 Board(){super(MainActivity.this);setBackgroundColor(Color.WHITE);setContentDescription("White drawing canvas");}
 void paintFor(Stroke s,int w,int h){paint.setColor(s.color);paint.setStrokeWidth(s.width*Math.min(w,h));paint.setStyle(Paint.Style.STROKE);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);}
 void drawStroke(Canvas c,Stroke s,int w,int h){if(s.points.isEmpty())return;paintFor(s,w,h);Path path=new Path();float[] first=s.points.get(0);path.moveTo(first[0]*w,first[1]*h);boolean hasLength=false;for(int i=1;i<s.points.size();i++){float[] q=s.points.get(i);if(q[0]!=first[0]||q[1]!=first[1])hasLength=true;path.lineTo(q[0]*w,q[1]*h);}if(hasLength)c.drawPath(path,paint);else c.drawPoint(first[0]*w,first[1]*h,paint);}
 void render(Canvas c,int w,int h){c.drawColor(Color.WHITE);for(Stroke s:lines)drawStroke(c,s,w,h);}
 void ensureCache(){int w=getWidth(),h=getHeight();if(w<1||h<1)return;if(cache==null||cache.getWidth()!=w||cache.getHeight()!=h){if(cache!=null)cache.recycle();cache=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);cached=new Canvas(cache);dirty=true;}if(dirty){cached.drawColor(Color.WHITE);for(Stroke s:lines)if(s!=current)drawStroke(cached,s,w,h);dirty=false;}}
 protected void onDraw(Canvas c){ensureCache();if(cache!=null)c.drawBitmap(cache,0,0,null);if(current!=null&&!current.points.isEmpty()){paintFor(current,getWidth(),getHeight());if(moved)c.drawPath(live,paint);else{float[] p=current.points.get(0);c.drawPoint(p[0]*getWidth(),p[1]*getHeight(),paint);}}}
 void finish(){if(current==null)return;ensureCache();if(cached!=null)drawStroke(cached,current,getWidth(),getHeight());current=null;pointer=-1;getParent().requestDisallowInterceptTouchEvent(false);postInvalidateOnAnimation();save();}
 void sample(MotionEvent e,int idx){for(int i=0;i<e.getHistorySize();i++)add(e.getHistoricalX(idx,i),e.getHistoricalY(idx,i));add(e.getX(idx),e.getY(idx));}
 public boolean onTouchEvent(MotionEvent e){if(loading||readFailed)return true;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){if(current!=null)finish();ensureCache();getParent().requestDisallowInterceptTouchEvent(true);pointer=e.getPointerId(e.getActionIndex());current=new Stroke(eraser?Color.WHITE:ink,(eraser?dp(26):dp(3))/(float)Math.max(1,Math.min(getWidth(),getHeight())));lines.add(current);live.reset();moved=false;add(e.getX(e.getActionIndex()),e.getY(e.getActionIndex()));postInvalidateOnAnimation();return true;}
 if(current==null)return true;int idx=e.findPointerIndex(pointer);if(action==MotionEvent.ACTION_CANCEL||idx<0){finish();return true;}if(action==MotionEvent.ACTION_MOVE){sample(e,idx);postInvalidateOnAnimation();}else if(action==MotionEvent.ACTION_UP||(action==MotionEvent.ACTION_POINTER_UP&&e.getPointerId(e.getActionIndex())==pointer)){sample(e,idx);finish();}return true;}
 void add(float x,float y){if(current==null||getWidth()<1||getHeight()<1)return;x=Math.max(0,Math.min(getWidth(),x));y=Math.max(0,Math.min(getHeight(),y));float nx=x/getWidth(),ny=y/getHeight();if(current.points.isEmpty())live.moveTo(x,y);else{float[] last=current.points.get(current.points.size()-1);if(last[0]==nx&&last[1]==ny)return;live.lineTo(x,y);moved=true;}current.points.add(new float[]{nx,ny});}
 }
 void save(){if(readFailed||board.current!=null)return;final ArrayList<Stroke> snapshot=new ArrayList<>(board.lines);final int rev=++revision;note("Saving locally...");disk.execute(()->{try{JSONArray all=new JSONArray();for(Stroke s:snapshot){JSONObject o=new JSONObject();o.put("color",s.color);o.put("width",s.width);JSONArray pts=new JSONArray();for(float[] p:s.points){JSONArray q=new JSONArray();q.put(p[0]);q.put(p[1]);pts.put(q);}o.put("points",pts);all.put(o);}File tmp=new File(getFilesDir(),"drawing.tmp");try(FileOutputStream f=new FileOutputStream(tmp)){f.write(all.toString().getBytes("UTF-8"));f.getFD().sync();}if(!tmp.renameTo(new File(getFilesDir(),"drawing.json")))throw new IOException("Could not commit drawing");main.post(()->{if(rev==revision)note("Saved on this tablet · "+snapshot.size()+" strokes");});}catch(Exception e){main.post(()->note("Save failed — keep app open"));}});}
 void load(){File f=new File(getFilesDir(),"drawing.json");if(!f.exists())return;try{File backup=new File(getFilesDir(),"drawing-before-v2.json");if(!backup.exists()){try(FileInputStream from=new FileInputStream(f);FileOutputStream to=new FileOutputStream(backup)){byte[] buf=new byte[8192];int n;while((n=from.read(buf))!=-1)to.write(buf,0,n);to.getFD().sync();}}ByteArrayOutputStream out=new ByteArrayOutputStream();try(FileInputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}JSONArray all=new JSONArray(out.toString("UTF-8"));ArrayList<Stroke> read=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject o=all.getJSONObject(i);Stroke s=new Stroke(o.getInt("color"),(float)o.getDouble("width"));JSONArray pts=o.getJSONArray("points");for(int j=0;j<pts.length();j++){JSONArray p=pts.getJSONArray(j);s.points.add(new float[]{(float)p.getDouble(0),(float)p.getDouble(1)});}read.add(s);}board.lines=read;board.current=null;board.dirty=true;board.invalidate();readFailed=false;note("Reopened locally · "+read.size()+" strokes");}catch(Exception e){readFailed=true;note("Saved drawing could not be opened; original retained");}}
 void export(){if(pendingExport!=null)pendingExport.recycle();pendingExport=Bitmap.createBitmap(Math.max(1,board.getWidth()),Math.max(1,board.getHeight()),Bitmap.Config.ARGB_8888);board.render(new Canvas(pendingExport),pendingExport.getWidth(),pendingExport.getHeight());Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/png");i.putExtra(Intent.EXTRA_TITLE,"Jane-Paper-"+System.currentTimeMillis()+".png");try{startActivityForResult(i,11);}catch(ActivityNotFoundException e){pendingExport.recycle();pendingExport=null;note("PNG export unavailable: no file picker");}}
 protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==11&&pendingExport!=null){try{if(c==RESULT_OK&&data!=null&&data.getData()!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null||!pendingExport.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException();}note("PNG exported to your chosen file");}}catch(Exception e){note("PNG export failed");}finally{pendingExport.recycle();pendingExport=null;}}}
 protected void onPause(){if(board!=null){if(board.current!=null)board.finish();else save();}super.onPause();}
}